syntax:
template <template <typename> class T> class ClassName {
    // class definition
};

code_example:
#include <iostream>

template <typename T>
struct Inner {
    static void display() { std::cout << "Inner template with type" << std::endl; }
};

template <template <typename> class T>
class Outer {
public:
    void call() { T<int>::display(); }
};

int main() {
    Outer<Inner> obj;
    obj.call();
    return 0;
}
